import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  Criteria,
  type FieldPath,
  type OrderDirection,
  type Filter,
  type Order,
  type FilterValueFor,
  type PathValue,
  type OperatorsForType,
  type CriteriaOptions,
  type Search,
} from "@woltz/rich-domain";
import type {
  UseCriteriaOptions,
  UseCriteriaReturn,
} from "../types/use-criteria.type";
import {
  loadCriteriaFromStorage,
  loadCriteriaFromUrl,
  removeCriteriaFromStorage,
  saveCriteriaToStorage,
  syncCriteriaWithUrl,
} from "../utils/persistence";

function applyInitials<T>(
  criteria: Criteria<T>,
  initialFilters: Filter<string, unknown>[],
  initialSort: Order[],
  initialSearch?: Search
) {
  if (!criteria.hasFilters() && initialFilters.length > 0) {
    initialFilters.forEach((filter) => {
      criteria.where(
        filter.field as FieldPath<T>,
        filter.operator as OperatorsForType<PathValue<T, FieldPath<T>>>,
        filter.value as FilterValueFor<PathValue<T, FieldPath<T>>>
      );
    });
  }

  if (!criteria.hasOrders() && initialSort.length > 0) {
    initialSort.forEach((sort) => {
      criteria.orderBy(sort.field as FieldPath<T>, sort.direction);
    });
  }

  if (!criteria.hasSearch() && initialSearch) {
    criteria.search(initialSearch);
  }
}

export function useCriteria<T = unknown>(
  options: UseCriteriaOptions<T> = {}
): UseCriteriaReturn<T> {
  const {
    initialPage = 1,
    pageSize = 20,
    initialFilters = [],
    initialSort = [],
    initialSearch,
    onChange,
    persistKey,
    syncWithUrl = false,
  } = options;

  const initialConfigRef = useRef({
    initialPage,
    pageSize,
    initialFilters,
    initialSort,
    initialSearch,
  });

  const buildCriteria = useCallback(
    (parts: {
      filters: Filter<string, unknown>[];
      orders: Order[];
      pagination: { page: number; limit: number; offset: number };
      search?: Search | null;
    }): Criteria<T> => {
      const criteria = Criteria.create<T>();

      parts.filters.forEach((f) =>
        criteria.where(
          f.field as FieldPath<T>,
          f.operator as OperatorsForType<PathValue<T, FieldPath<T>>>,
          f.value as FilterValueFor<PathValue<T, FieldPath<T>>>,
          f.options
        )
      );
      parts.orders.forEach((o) =>
        criteria.orderBy(o.field as FieldPath<T>, o.direction)
      );
      criteria.paginate(parts.pagination.page, parts.pagination.limit);
      if (parts.search) criteria.search(parts.search);

      return criteria;
    },
    []
  );

  const createInitialCriteria = useCallback((): Criteria<T> => {
    if (syncWithUrl) {
      const fromUrl = loadCriteriaFromUrl<T>();

      if (fromUrl) {
        applyInitials<T>(fromUrl, initialFilters, initialSort, initialSearch);
        return fromUrl;
      }
    }

    if (persistKey) {
      const fromStorage = loadCriteriaFromStorage<T>(persistKey);
      if (fromStorage) {
        applyInitials<T>(
          fromStorage,
          initialFilters,
          initialSort,
          initialSearch
        );
        return fromStorage;
      }
    }

    const criteria = Criteria.create<T>().paginate(initialPage, pageSize);
    applyInitials(criteria, initialFilters, initialSort, initialSearch);

    return criteria;
  }, [
    initialPage,
    pageSize,
    initialFilters,
    initialSort,
    initialSearch,
    persistKey,
    syncWithUrl,
  ]);

  const [criteria, setCriteria] = useState<Criteria<T>>(createInitialCriteria);

  useEffect(() => {
    if (persistKey) {
      saveCriteriaToStorage(persistKey, criteria);
    }

    if (syncWithUrl) {
      syncCriteriaWithUrl(criteria);
    }

    onChange?.(criteria);
  }, [criteria, onChange, persistKey, syncWithUrl]);

  const filters = useMemo(() => criteria.getFilters(), [criteria]);
  const sorting = useMemo(() => criteria.getOrders(), [criteria]);
  const pagination = useMemo(() => criteria.getPagination(), [criteria]);
  const search = useMemo(() => {
    if (!criteria.hasSearch()) return null;
    return criteria.getSearch()!;
  }, [criteria]);

  const addFilter = useCallback(
    <K extends FieldPath<T>>(
      field: K,
      operator: OperatorsForType<PathValue<T, K>>,
      value?: FilterValueFor<PathValue<T, K>>,
      options?: CriteriaOptions
    ) => {
      setCriteria((prev) => {
        const currentFilters = prev.getFilters();

        const existingIndex = currentFilters.findIndex(
          (f) => f.field === field
        );

        let newFilters;
        if (existingIndex !== -1) {
          newFilters = [...currentFilters];
          newFilters[existingIndex] = { field, operator, value, options };
        } else {
          newFilters = [...currentFilters, { field, operator, value, options }];
        }

        return buildCriteria({
          filters: newFilters,
          orders: prev.getOrders(),
          pagination: prev.getPagination(),
          search: prev.hasSearch() ? prev.getSearch() : null,
        });
      });
    },
    [buildCriteria]
  );

  const removeFilter = useCallback(
    (index: number) => {
      setCriteria((prev) => {
        const currentFilters = prev.getFilters();
        const newFilters = currentFilters.filter((_, i) => i !== index);

        return buildCriteria({
          filters: newFilters,
          orders: prev.getOrders(),
          pagination: prev.getPagination(),
          search: prev.hasSearch() ? prev.getSearch() : null,
        });
      });
    },
    [buildCriteria]
  );

  const addOrReplaceByIndex = useCallback(
    (props: {
      field: FieldPath<T>;
      operator: OperatorsForType<PathValue<T, FieldPath<T>>>;
      value?: FilterValueFor<PathValue<T, FieldPath<T>>>;
      options?: CriteriaOptions;
      replaceIndex?: number;
    }) => {
      const { field, operator, value, options, replaceIndex } = props;
      setCriteria((prev) => {
        const currentFilters = prev.getFilters();
        const newFilters = [...currentFilters];
        if (replaceIndex !== undefined) {
          newFilters[replaceIndex] = { field, operator, value, options };
        } else {
          newFilters.push({ field, operator, value, options });
        }
        return buildCriteria({
          filters: newFilters,
          orders: prev.getOrders(),
          pagination: prev.getPagination(),
          search: prev.hasSearch() ? prev.getSearch() : null,
        });
      });
    },
    [buildCriteria]
  );

  const getFilterByField = useCallback(
    <K extends FieldPath<T>>(field: K) => {
      return filters.find((f) => f.field === field) as
        | Filter<string, FilterValueFor<PathValue<T, K>>>
        | undefined;
    },
    [filters]
  );

  const getSortByField = useCallback(
    <K extends FieldPath<T>>(field: K) => {
      return sorting.find((s) => s.field === field) as Order | undefined;
    },
    [sorting]
  );

  const removeFilterByField = useCallback(
    (field: FieldPath<T>) => {
      setCriteria((prev) => {
        const currentFilters = prev.getFilters();
        const newFilters = currentFilters.filter((f) => f.field !== field);

        return buildCriteria({
          filters: newFilters,
          orders: prev.getOrders(),
          pagination: prev.getPagination(),
          search: prev.hasSearch() ? prev.getSearch() : null,
        });
      });
    },
    [buildCriteria]
  );

  const clearFilters = useCallback(() => {
    setCriteria((prev) => {
      return buildCriteria({
        filters: [],
        orders: prev.getOrders(),
        pagination: prev.getPagination(),
        search: prev.hasSearch() ? prev.getSearch() : null,
      });
    });
  }, [buildCriteria]);

  const addSort = useCallback(
    (field: FieldPath<T>, direction: OrderDirection = "asc") => {
      setCriteria((prev) => {
        const currentOrders = prev.getOrders();
        let newOrders: Order[] = [{ field: String(field), direction }];

        const existingIndex = currentOrders.findIndex((o) => o.field === field);
        if (existingIndex !== -1) {
          newOrders = [...currentOrders];
          newOrders[existingIndex] = { field: String(field), direction };
        } else {
          newOrders = [...currentOrders, { field: String(field), direction }];
        }

        return buildCriteria({
          filters: prev.getFilters(),
          orders: newOrders,
          pagination: prev.getPagination(),
          search: prev.hasSearch() ? prev.getSearch() : null,
        });
      });
    },
    [buildCriteria]
  );

  const removeSort = useCallback(
    (index: number) => {
      setCriteria((prev) => {
        const currentOrders = prev.getOrders();
        const newOrders = currentOrders.filter((_, i) => i !== index);

        return buildCriteria({
          filters: prev.getFilters(),
          orders: newOrders,
          pagination: prev.getPagination(),
          search: prev.hasSearch() ? prev.getSearch() : null,
        });
      });
    },
    [buildCriteria]
  );

  const removeSortByField = useCallback(
    (field: FieldPath<T>) => {
      setCriteria((prev) => {
        const currentOrders = prev.getOrders();
        const newOrders = currentOrders.filter((o) => o.field !== field);

        return buildCriteria({
          filters: prev.getFilters(),
          orders: newOrders,
          pagination: prev.getPagination(),
          search: prev.hasSearch() ? prev.getSearch() : null,
        });
      });
    },
    [buildCriteria]
  );

  const clearSort = useCallback(() => {
    setCriteria((prev) => {
      return buildCriteria({
        filters: prev.getFilters(),
        orders: [],
        pagination: prev.getPagination(),
        search: prev.hasSearch() ? prev.getSearch() : null,
      });
    });
  }, [buildCriteria]);

  const setPage = useCallback(
    (page: number) => {
      setCriteria((prev) => {
        const pag = prev.getPagination();
        return buildCriteria({
          filters: prev.getFilters(),
          orders: prev.getOrders(),
          pagination: { ...pag, page, offset: (page - 1) * pag.limit },
          search: prev.hasSearch() ? prev.getSearch() : null,
        });
      });
    },
    [buildCriteria]
  );

  const setPageSize = useCallback(
    (size: number) => {
      setCriteria((prev) => {
        return buildCriteria({
          filters: prev.getFilters(),
          orders: prev.getOrders(),
          pagination: { page: 1, limit: size, offset: 0 },
          search: prev.hasSearch() ? prev.getSearch() : null,
        });
      });
    },
    [buildCriteria]
  );

  const nextPage = useCallback(() => {
    setCriteria((prev) => {
      const pag = prev.getPagination();
      const newPage = pag.page + 1;
      return buildCriteria({
        filters: prev.getFilters(),
        orders: prev.getOrders(),
        pagination: {
          ...pag,
          page: newPage,
          offset: (newPage - 1) * pag.limit,
        },
        search: prev.hasSearch() ? prev.getSearch() : null,
      });
    });
  }, [buildCriteria]);

  const prevPage = useCallback(() => {
    setCriteria((prev) => {
      const pag = prev.getPagination();
      if (pag.page > 1) {
        const newPage = pag.page - 1;
        return buildCriteria({
          filters: prev.getFilters(),
          orders: prev.getOrders(),
          pagination: {
            ...pag,
            page: newPage,
            offset: (newPage - 1) * pag.limit,
          },
          search: prev.hasSearch() ? prev.getSearch() : null,
        });
      }
      return prev;
    });
  }, [buildCriteria]);

  const setSearch = useCallback(
    (value: string) => {
      setCriteria((prev) => {
        return buildCriteria({
          filters: prev.getFilters(),
          orders: prev.getOrders(),
          pagination: prev.getPagination(),
          search: value,
        });
      });
    },
    [buildCriteria]
  );

  const clearSearch = useCallback(() => {
    setCriteria((prev) => {
      return buildCriteria({
        filters: prev.getFilters(),
        orders: prev.getOrders(),
        pagination: prev.getPagination(),
        search: null,
      });
    });
  }, [buildCriteria]);

  const reset = useCallback(() => {
    const config = initialConfigRef.current;

    const newCriteria = Criteria.create<T>().paginate(
      config.initialPage,
      config.pageSize
    );

    config.initialFilters.forEach((filter) => {
      newCriteria.where(
        filter.field,
        filter.operator as OperatorsForType<PathValue<T, FieldPath<T>>>,
        filter.value as FilterValueFor<PathValue<T, FieldPath<T>>>,
        filter.options
      );
    });

    config.initialSort.forEach((sort) => {
      newCriteria.orderBy(sort.field as FieldPath<T>, sort.direction);
    });

    if (config.initialSearch) {
      newCriteria.search(config.initialSearch);
    }

    setCriteria(newCriteria);

    if (persistKey) {
      removeCriteriaFromStorage(persistKey);
    }
  }, [persistKey]);

  const toJSON = useCallback(() => criteria.toJSON(), [criteria]);

  const clone = useCallback(() => criteria.clone(), [criteria]);

  const clearAll = useCallback(() => {
    setCriteria(Criteria.create<T>());
  }, []);

  return {
    criteria,
    addOrReplaceByIndex,
    filters,
    sorting,
    pagination,
    search,
    addFilter,
    getSortByField,
    getFilterByField,
    removeFilter,
    removeFilterByField,
    clearFilters,
    addSort,
    removeSort,
    removeSortByField,
    clearSort,
    setPage,
    setPageSize,
    nextPage,
    prevPage,
    setSearch,
    clearSearch,
    reset,
    toJSON,
    clone,
    clearAll,
  };
}

import type {
  Criteria,
  FieldPath,
  Filter,
  Order,
  OrderDirection,
  Pagination,
  Search,
  FilterValueFor,
  PathValue,
  OperatorsForType,
  CriteriaOptions,
} from "@woltz/rich-domain";

/**
 * Configuration options for useCriteria hook
 */
export interface UseCriteriaOptions<T> {
  /**
   * Initial page number (default: 1)
   */
  initialPage?: number;

  /**
   * Items per page (default: 20)
   */
  pageSize?: number;

  /**
   * Initial filters to apply
   */
  initialFilters?: Filter<FieldPath<T>, unknown>[];

  /**
   * Initial sorting
   */
  initialSort?: Order[];

  /**
   * Initial search configuration
   */
  initialSearch?: Search;

  /**
   * Callback fired when criteria changes
   */
  onChange?: (criteria: Criteria<T>) => void;

  /**
   * Enable persistence in localStorage
   */
  persistKey?: string;

  /**
   * Enable persistence in URL query params
   */
  syncWithUrl?: boolean;
}

/**
 * Return type for useCriteria hook
 */
export interface UseCriteriaReturn<T> {
  /**
   * Current criteria instance
   */
  criteria: Criteria<T>;

  /**
   * Current filters
   */
  filters: Array<Filter<string, unknown>>;

  /**
   * Current sorting
   */
  sorting: Order[];

  /**
   * Current pagination state
   */
  pagination: Pagination;

  /**
   * Current search state
   */
  search: Search | null;

  /**
   * Add a filter. If a filter for the same field exists, it will be replaced.
   */
  addFilter: <K extends FieldPath<T>>(
    field: K,
    operator: OperatorsForType<PathValue<T, K>>,
    value?: FilterValueFor<PathValue<T, K>>,
    options?: CriteriaOptions
  ) => void;

  /**
   * Remove a filter by index
   */
  removeFilter: (index: number) => void;

  /**
   * Remove a filter by field name
   */
  removeFilterByField: (field: FieldPath<T>) => void;

  /**
   * Clear all filters
   */
  clearFilters: () => void;

  /**
   * Add sorting. If sorting for the same field exists, it will be replaced.
   */
  addSort: (field: FieldPath<T>, direction?: OrderDirection) => void;

  /**
   * Remove sort by index
   */
  removeSort: (index: number) => void;

  /**
   * Replace a filter by index
   */
  addOrReplaceByIndex: (props: {
    field: FieldPath<T>;
    operator: OperatorsForType<PathValue<T, FieldPath<T>>>;
    value?: FilterValueFor<PathValue<T, FieldPath<T>>>;
    options?: CriteriaOptions;
    replaceIndex?: number;
  }) => void;
  /**
   * Remove sort by field name
   */
  removeSortByField: (field: FieldPath<T>) => void;

  /**
   * Get filter by field name
   */
  getFilterByField: <K extends FieldPath<T>>(
    field: K
  ) => Filter<string, FilterValueFor<PathValue<T, K>>> | undefined;

  /**
   * Get sort by field name
   */
  getSortByField: <K extends FieldPath<T>>(field: K) => Order | undefined;

  /**
   * Clear all sorting
   */
  clearSort: () => void;

  /**
   * Set page number
   */
  setPage: (page: number) => void;

  /**
   * Set page size (resets to page 1)
   */
  setPageSize: (size: number) => void;

  /**
   * Go to next page
   */
  nextPage: () => void;

  /**
   * Go to previous page
   */
  prevPage: () => void;

  /**
   * Set search
   */
  setSearch: (value: string) => void;

  /**
   * Clear search
   */
  clearSearch: () => void;

  /**
   * Reset to initial state
   */
  reset: () => void;

  /**
   * Get current criteria as JSON
   */
  toJSON: () => ReturnType<Criteria<T>["toJSON"]>;

  /**
   * Clone current criteria
   */
  clone: () => Criteria<T>;

  /**
   * Clear all criteria
   */
  clearAll: () => void;
}

import { Criteria } from "@woltz/rich-domain";

export function saveCriteriaToStorage<T>(
  key: string,
  criteria: Criteria<T>
): void {
  try {
    const json = criteria.toJSON();
    localStorage.setItem(key, JSON.stringify(json));
  } catch (error) {
    console.warn("Failed to save criteria to localStorage:", error);
  }
}

export function loadCriteriaFromStorage<T>(key: string): Criteria<T> | null {
  try {
    const stored = localStorage.getItem(key);
    if (!stored) return null;

    const json = JSON.parse(stored);
    return Criteria.fromObject<T>(json);
  } catch (error) {
    console.warn("Failed to load criteria from localStorage:", error);
    return null;
  }
}

export function removeCriteriaFromStorage(key: string): void {
  try {
    localStorage.removeItem(key);
  } catch (error) {
    console.warn("Failed to remove criteria from localStorage:", error);
  }
}

export function syncCriteriaWithUrl<T>(criteria: Criteria<T>): void {
  if (typeof window === "undefined") return;

  const params = criteria.toQueryParams();
  const url = new URL(window.location.href);
  url.search = params.toString();

  window.history.replaceState({}, "", url.toString());
}

export function loadCriteriaFromUrl<T>(): Criteria<T> | null {
  if (typeof window === "undefined") return null;

  try {
    const params = new URLSearchParams(window.location.search);
    const query: Record<string, unknown> = {};
    params.forEach((value, key) => {
      query[key] = value;
    });

    if (Object.keys(query).length === 0) return null;

    return Criteria.fromQueryParams<T>(query);
  } catch (error) {
    console.warn("Failed to load criteria from URL:", error);
    return null;
  }
}
